        except re.error: return False
    lohi = wanted.split('..')
    if len(lohi) == 2:
        a, b = lohi
        a='' if a.lower() in ('none','-') else a
        b='' if b.lower() in ('none','-') else b
        # Ranges are only defined for dates, priorities, numeric fields and ID.
        if field in ('project','context','hashtag','subject'):
            return False
        matched = False
        for x in vals:
            xv, av, bv = x, a, b
            if field in ('due','created','completed') or field.endswith('_date') or (_dateval(x) is not None and (not a or _dateval(a) is not None or a.lower()=='none') and (not b or _dateval(b) is not None or b.lower()=='none')):
                xv = _dateval(x); av = _dateval(a) if a and a.lower()!='none' else None; bv = _dateval(b) if b and b.lower()!='none' else None
            elif field == 'priority':
                if len(x) != 1 or (a and len(a) != 1) or (b and len(b) != 1): continue
                xv = ord(x.upper()); av = ord(a.upper()) if a else None; bv = ord(b.upper()) if b else None
            elif field == 'id':
                xv=float(x); av=float(a) if a else None; bv=float(b) if b else None
            elif field.endswith(('_dur','_duration')) or field == 'spent' or _duration_seconds(x) is not None:
                xv=_duration_seconds(x); av=_duration_seconds(a) if a else None; bv=_duration_seconds(b) if b else None
            elif field.endswith(('_sz','_size')) or (_size_bytes(x) is not None and re.search(r'[A-Za-z]', x)):
                xv=_size_bytes(x); av=_size_bytes(a) if a else None; bv=_size_bytes(b) if b else None
            elif field.endswith('_time'):
                xv=_time_minutes(x); av=_time_minutes(a) if a else None; bv=_time_minutes(b) if b else None
            elif (re.fullmatch(r'-?\d+(?:\.\d+)?', x) and (not a or re.fullmatch(r'-?\d+(?:\.\d+)?', a)) and (not b or re.fullmatch(r'-?\d+(?:\.\d+)?', b))):
                xv = float(x); av = float(a) if a else None; bv = float(b) if b else None
            else:
                return False
            if xv is None: continue
            try:
                if (av is None or xv >= av) and (bv is None or xv <= bv): matched = True
            except TypeError: pass
        return matched
    if field in ('due','created','completed') or field.endswith('_date') or any(re.fullmatch(r'\d{4}-\d{2}-\d{2}', x) for x in vals):
        wanted_date = _dateval(wanted)
        if wanted_date is not None:
