def matches_filter(todo, expression, regex=False):
    """Return whether todo matches a --filter expression (empty matches all)."""
    if not expression: return True
    sep = '~' if '~' in expression or regex else '|'
    for rule in expression.split(sep):
        passed = True
        for condition in rule.split(';'):
            cond = condition.strip()
            if not cond:
                continue
            negative = cond.startswith(('-', '!'))
            if negative: cond = cond[1:]
            if '=' in cond: key, raw = cond.split('=', 1)
            else: key, raw = cond, 'any'
            key = key.strip()
            field = ALIASES.get(key, 'tag:id' if key == 'id' else key)
            # done is a presence marker, not an ordinary valued field.
            if field == 'done':
                value = bool(_get(todo, 'done') or _get(todo, 'completed'))
                ok = value if raw.lower() in ('any', 'true', '1') else not value if raw.lower() in ('none','-','false','0') else value
            else:
                value = _get(todo, field)
                parts = raw.split(',')
                ok = any(_match_value(value, p.strip(), field, regex) for p in parts)
                neg_values = [p.strip() for p in parts if p.strip().startswith('-') and p.strip() not in ('-','none') and '..' not in p]
                if neg_values:
